namespace Idasletten.Shared.Entities;

/// <summary>Has one or more TournamentPlayers, scoped to a single match.</summary>
public class TournamentTeam
{
    public Guid Id { get; set; }
    public Guid MatchId { get; set; }
    public TournamentMatch Match { get; set; } = null!;

    /// <summary>Not an input field — autogenerated "Team 1", "Team 2", etc.</summary>
    public string Name { get; set; } = string.Empty;

    /// <summary>Not an input field — autogenerated 1, 2, etc.</summary>
    public int Number { get; set; }

    public List<TournamentTeamPlayer> TeamPlayers { get; set; } = [];
}

/// <summary>Join entity between TournamentTeam and TournamentPlayer.</summary>
public class TournamentTeamPlayer
{
    public Guid TeamId { get; set; }
    public TournamentTeam Team { get; set; } = null!;

    public Guid TournamentPlayerId { get; set; }
    public TournamentPlayer TournamentPlayer { get; set; } = null!;
}
